223	  /* ── render ──────────────────────────────────────────────── */
224	  function render(insights) {
225	    allInsights = insights;
226	
227	    var vals     = getDistinctValues(insights);
228	    var categories = vals.categories;
229	    var projects   = vals.projects;
230	
231	    var filtered = applyFilters();
232	
233	    app.innerHTML =
234	      '<div class="page-header"><h1>Knowledge</h1></div>' +
235	      '<div class="knowledge-tabs">' +
236	        '<button class="knowledge-tab' + (activeTab === 'global' ? ' active' : '') + '" data-tab="global">Global</button>' +
237	        '<button class="knowledge-tab' + (activeTab === 'project' ? ' active' : '') + '" data-tab="project">Repository</button>' +
238	      '</div>' +
239	      '<div class="filter-bar" id="kn-filter-bar">' +
240	        buildFilterBarHtml(categories, projects) +
241	      '</div>' +
242	      '<div id="knowledge-list">' + buildKnowledgeHtml(filtered) + '</div>';
243	
244	    wireEvents(categories, projects);
245	    wireRangeSliders();
246	  }
247	
248	  /* ── renderList ─── partial re-render of the card list only ─ */
249	  function renderList(categories, projects) {
250	    /* Capture focus state before DOM mutation so we can restore it conditionally */

250	    /* Capture focus state before DOM mutation so we can restore it conditionally */
251	    var activeEl  = document.activeElement;
252	    var hadFocus  = activeEl && activeEl.id === 'kn-query';
253	
254	    var filtered = applyFilters();
255	    var listEl = document.getElementById('knowledge-list');
256	    if (listEl) {
257	      listEl.innerHTML = buildKnowledgeHtml(filtered);
258	    }
259	    wireRangeSliders();
260	    /* Re-wire filter bar if tab changed (may have added/removed project dropdown) */
261	    var filterBarEl = document.getElementById('kn-filter-bar');
262	    if (filterBarEl) {
263	      filterBarEl.innerHTML = buildFilterBarHtml(categories, projects);
264	      wireFilterBarEvents(filterBarEl);
265	    }
266	
267	    /* Restore search-input focus only when it was focused before the re-render.
268	       Unconditional .focus() would steal focus from card action buttons (edit,
269	       cancel, delete, move), causing a UX regression on those interactions. */
270	    if (hadFocus) {
271	      var qEl = document.getElementById('kn-query');
272	      if (qEl) qEl.focus();
273	    }
274	  }
275	
276	  /* ── wireRangeSliders ─── live confidence label updates ─────── */
277	  function wireRangeSliders() {
278	    var inputs = document.querySelectorAll('input[type="range"][id^="kn-edit-conf-"]');
279	    inputs.forEach(function (input) {
280	      var idStr = input.id.replace('kn-edit-conf-', '');
281	      input.addEventListener('input', function () {
282	        var labelEl = document.getElementById('kn-conf-label-' + idStr);
283	        if (labelEl) labelEl.textContent = formatConfidence(parseFloat(this.value));
284	      });
285	    });
286	  }
287	
288	  /* ── wireFilterBarEvents ─── attach change/input to filter controls ── */
289	  function wireFilterBarEvents(filterBarEl) {
290	    var catEl  = filterBarEl.querySelector('#kn-category');
291	    var projEl = filterBarEl.querySelector('#kn-project');
292	    var qEl    = filterBarEl.querySelector('#kn-query');
293	
294	    /* Collect categories/projects via shared helper */
295	    var vals       = getDistinctValues(allInsights);
296	    var categories = vals.categories;
297	    var projects   = vals.projects;
298	
299	    if (catEl) {
300	      catEl.addEventListener('change', function () {
301	        filterCategory = this.value;
302	        renderList(categories, projects);
303	      });
304	    }
305	    if (projEl) {
306	      projEl.addEventListener('change', function () {
307	        filterProject = this.value;
308	        renderList(categories, projects);
309	      });
310	    }
311	    if (qEl) {
312	      qEl.addEventListener('input', function () {
313	        filterQuery = this.value;
314	        renderList(categories, projects);
315	      });
316	    }
317	  }
318	
319	  /* ── wireEvents ──────────────────────────────────────────── */
320	  function wireEvents(categories, projects) {
321	    /* Tab bar */
322	    var tabButtons = document.querySelectorAll('.knowledge-tab');
323	    tabButtons.forEach(function (btn) {
324	      btn.addEventListener('click', function () {
325	        var newTab = this.getAttribute('data-tab');
326	        if (newTab === activeTab) return;
327	        activeTab       = newTab;
328	        filterCategory  = '';
329	        filterProject   = '';
330	        filterQuery     = '';
331	        editingId       = null;
332	        confirmDeleteId = null;
333	        movingId        = null;
334	
335	        /* Update active class */
336	        tabButtons.forEach(function (b) {
337	          b.classList.toggle('active', b.getAttribute('data-tab') === activeTab);
338	        });
339	
340	        renderList(categories, projects);
341	      });
342	    });
343	
344	    /* Wire filter bar */
345	    var filterBarEl = document.getElementById('kn-filter-bar');
346	    if (filterBarEl) wireFilterBarEvents(filterBarEl);
347	
348	    /* Event delegation for card actions */
349	    var listEl = document.getElementById('knowledge-list');
350	    if (!listEl) return;
351	
352	    listEl.addEventListener('click', function (e) {
353	      var btn = e.target.closest('[data-action]');
354	      if (!btn) return;
355	
356	      var action = btn.getAttribute('data-action');
357	      var rawId  = btn.getAttribute('data-id');
358	      var id     = parseInt(rawId, 10);
359	
360	      if (action === 'edit') {
361	        editingId       = id;
362	        confirmDeleteId = null;
363	        movingId        = null;
364	        renderList(categories, projects);
365	        return;
366	      }
367	
368	      if (action === 'cancel-edit') {
369	        editingId = null;
370	        renderList(categories, projects);
371	        return;
372	      }
373	
374	      if (action === 'delete') {
375	        confirmDeleteId = id;
376	        editingId       = null;
377	        movingId        = null;
378	        renderList(categories, projects);
379	        return;
380	      }
381	
382	      if (action === 'cancel-delete') {
383	        confirmDeleteId = null;
384	        renderList(categories, projects);
385	        return;
386	      }
387	
388	      if (action === 'move') {
389	        movingId        = id;
390	        editingId       = null;
391	        confirmDeleteId = null;
392	        renderList(categories, projects);
393	        return;
394	      }
395	
396	      if (action === 'cancel-move') {
397	        movingId = null;
398	        renderList(categories, projects);
399	        return;
400	      }
401	
402	      /* ── Confirm delete ── */
403	      if (action === 'confirm-delete') {
404	        var delScope = btn.getAttribute('data-scope');
405	        var delSlug  = btn.getAttribute('data-slug') || null;
406	        API.deleteKnowledge(id, delScope, delSlug).then(function () {
407	          allInsights = allInsights.filter(function (ins) { return ins.id !== id; });
408	          confirmDeleteId = null;
409	          renderList(categories, projects);
410	        }).catch(function (err) {
411	          showError(app, 'Delete failed: ' + (err.message || String(err)));
412	        });
413	        return;
414	      }
415	
416	      /* ── Promote to Global ── */
417	      if (action === 'promote') {
